package com.oms.order.service;

import org.junit.jupiter.api.*;
import com.ruoyi.common.core.domain.R;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Real MySQL regressions: scope claims, source facts, safe retries and merchant rules. */
class RefundWorkflowTest {
 RefundServiceTest f=new RefundServiceTest();RefundGoodsTasks tasks;RefundFlowAutomation flow;long refund,line;
 @BeforeAll static void start(){RefundServiceTest.start();}
 @BeforeEach void setup(){f.reset();tasks=new RefundGoodsTasks();tasks.refunds=f.refunds;tasks.inventory=mock(OrderWarehouseClient.class);f.workspace.goodsTasks=tasks;line=f.db.queryForObject("SELECT id FROM oms_order_line",Long.class);refund=f.convert(f.ingest(f.source(1,"25.00","WAIT_SELLER_AGREE")));flow=new RefundFlowAutomation();flow.refunds=f.refunds;flow.workspace=f.workspace;flow.execution=mock(RefundPlatformExecution.class);}
 @AfterEach void clear(){f.clear();}
 Map<String,Object> mixed(long qty){Map<String,Object> review=f.review(refund,"CANCEL","MIXED");review.put("goods_tasks",Collections.singletonList(m("action","CANCEL","order_line_id",line,"quantity",qty)));return review;}
 long adopt(long qty){f.workspace.review("VERIFY",refund,mixed(qty),"test");return f.db.queryForObject("SELECT id FROM oms_refund_goods_task WHERE state<>'CANCELED'",Long.class);}
 Map<String,Object> receipt(String request,long canceled){return m("request_id",request,"state","COMPLETED","lines",Collections.singletonList(m("platform_oid","987654321012345679","sku_sn","A","cancelled_quantity",canceled,"reserved_quantity",5-canceled)));}
 void rule(){Map<String,Object> policy=RefundFlowAutomation.defaults();policy.put("auto_full_cancel",1);f.db.update("INSERT INTO oms_refund_flow_policy(company_code,channel_id,enabled,policy_json,updated_by) VALUES ('VERIFY',1,1,?,'test')",encode(policy));f.db.update("INSERT INTO oms_refund_flow_task(company_code,refund_id) VALUES ('VERIFY',?)",refund);f.db.update("UPDATE oms_order SET document_info=? WHERE id=?",encode(m("lines",Collections.singletonList(m("platform_oid","987654321012345679","goods_payment","25.00","payment_source","平台分摊实付（已核对不含运费）")))),f.order);}
 @Test void cancellationProjectsConfirmedInventoryReceiptOnlyOnce(){long task=adopt(3);when(tasks.inventory.adjust(eq("VERIFY"),anyMap(),anyString())).thenAnswer(call->{Map<String,Object> command=call.getArgument(1);return R.ok(receipt(text(command,"request_id"),3));});tasks.process("VERIFY",task);tasks.process("VERIFY",task);assertEquals(3,f.db.queryForObject("SELECT cancelled_quantity FROM oms_order_line",Integer.class));assertEquals(2,f.db.queryForObject("SELECT reserved_quantity FROM oms_order_line",Integer.class));assertEquals("DONE",f.refunds.business("VERIFY",refund,false).get("goods_state"));verify(tasks.inventory,times(1)).adjust(eq("VERIFY"),anyMap(),anyString());}
 @Test void unknownStockResultIsQueriedByOriginalIdEvenAfterPlatformChanged(){long task=adopt(3);when(tasks.inventory.adjust(eq("VERIFY"),anyMap(),anyString())).thenThrow(new IllegalStateException("timeout"));tasks.process("VERIFY",task);assertEquals(0,f.db.queryForObject("SELECT cancelled_quantity FROM oms_order_line",Integer.class));String request=f.db.queryForObject("SELECT request_id FROM oms_refund_goods_task",String.class);f.ingest(f.source(2,"20.00","WAIT_SELLER_AGREE"));when(tasks.inventory.adjustmentReceipt(eq("VERIFY"),eq(request),anyString())).thenReturn(R.ok(receipt(request,3)));tasks.process("VERIFY",task);assertEquals(3,f.db.queryForObject("SELECT cancelled_quantity FROM oms_order_line",Integer.class));assertEquals("STALE",f.refunds.business("VERIFY",refund,false).get("review_state"));verify(tasks.inventory,times(1)).adjust(eq("VERIFY"),anyMap(),anyString());}
 @Test void issuedCancellationCannotBeHiddenByPlatformClosure(){long task=adopt(3);f.db.update("UPDATE oms_refund_goods_task SET state='UNKNOWN',command_json='{}' WHERE id=?",task);f.ingest(f.source(2,"25.00","CLOSED"));assertNotEquals("CLOSED",f.refunds.business("VERIFY",refund,false).get("state"));assertNotEquals("CANCELED",f.refunds.business("VERIFY",refund,false).get("goods_state"));}
 @Test void claimedTaskCannotBeReplacedByAnotherQuantity(){long task=adopt(3);f.db.update("UPDATE oms_refund_goods_task SET state='PROCESSING',lease_token='worker',lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE id=?",task);assertThrows(IllegalArgumentException.class,()->f.workspace.review("VERIFY",refund,mixed(2),"test"));assertEquals(3,f.db.queryForObject("SELECT quantity FROM oms_refund_goods_task",Integer.class));}
 @Test void sameExecutedScopeCanBeReviewedWithoutAnotherStockRequest(){long task=adopt(3);f.db.update("UPDATE oms_refund_goods_task SET state='UNKNOWN',command_json='{}' WHERE id=?",task);f.ingest(f.source(2,"20.00","WAIT_SELLER_AGREE"));f.workspace.review("VERIFY",refund,mixed(3),"test");assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task",Integer.class));assertEquals("APPROVED",f.refunds.business("VERIFY",refund,false).get("review_state"));verifyNoInteractions(tasks.inventory);}
 @Test void twoRefundsCannotClaimSameUnshippedUnits(){adopt(3);Map<String,Object> source=f.source(1,"25.00","WAIT_SELLER_AGREE"),parsed=parse(text(source,"jdp_response"));parsed.put("refund_id","9007199254740994");source.put("refund_id",parsed.get("refund_id"));source.put("jdp_response",encode(m("refund",parsed)));long second=f.convert(f.ingest(source));Map<String,Object> review=f.review(second,"CANCEL","CANCEL");review.put("cancel_line_id",line);review.put("cancel_quantity",3);assertThrows(IllegalArgumentException.class,()->f.workspace.review("VERIFY",second,review,"test"));}
 @Test void unrelatedSuborderAndShipmentRemainAvailable(){f.db.update("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,reserved_quantity) VALUES ('VERIFY',?,'987654321012345680','B','其他子单',2,10,2)",f.order);f.refunds.tx().execute(tx->{RefundGuard.refresh(f.repo,"VERIFY",1,"987654321012345678");return null;});assertEquals("",f.db.queryForObject("SELECT refund_block_reason FROM oms_order WHERE id=?",String.class,f.order));assertFalse(f.db.queryForObject("SELECT refund_block_reason FROM oms_order_line WHERE id=?",String.class,line).isEmpty());assertEquals("",f.db.queryForObject("SELECT refund_block_reason FROM oms_order_line WHERE sku_sn='B'",String.class));assertEquals(1,number(f.refunds.businessList("VERIFY",Collections.singletonMap("fulfillmentStage","UNSHIPPED")),"total"));}
 @Test void actualStageFilterUsesOutboundAndUnknownState(){f.shipped();f.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=2");assertEquals(1,number(f.refunds.businessList("VERIFY",Collections.singletonMap("fulfillmentStage","PART_SHIPPED")),"total"));assertEquals(0,number(f.refunds.businessList("VERIFY",Collections.singletonMap("fulfillmentStage","SHIPPED")),"total"));f.db.update("UPDATE oms_order_shipment SET status='DISPATCHING'");assertEquals(1,number(f.refunds.businessList("VERIFY",Collections.singletonMap("fulfillmentStage","UNKNOWN")),"total"));}
 @Test void explicitFullCancellationRuleRecordsEvidenceAndQueuesOnlyLocalTasks(){rule();Map<String,Object> result=flow.step("VERIFY",refund,1);assertEquals("WAITING",result.get("state"));assertEquals("MIXED",f.refunds.business("VERIFY",refund,false).get("goods_action"));assertEquals(5,f.db.queryForObject("SELECT quantity FROM oms_refund_goods_task",Integer.class));assertTrue(text(f.refunds.business("VERIFY",refund,false),"review_evidence").contains("25.00"));verifyNoInteractions(flow.execution,tasks.inventory);}
 @Test void partialAmountAndDifferenceKeywordsNeverInferCancellation(){rule();f.ingest(f.source(2,"2.00","WAIT_SELLER_AGREE"));assertEquals("MANUAL",flow.step("VERIFY",refund,1).get("state"));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task",Integer.class));}
 @Test void changedOriginalOrderPreventsAutomaticDecision(){rule();f.db.update("UPDATE oms_platform_order SET change_pending=1");assertEquals("MANUAL",flow.step("VERIFY",refund,1).get("state"));verifyNoInteractions(tasks.inventory);}
 @Test void confirmedPureMoneyPlanHasPriorityOverAutomaticCancelRule(){rule();f.workspace.review("VERIFY",refund,f.review(refund,"COMPENSATION","KEEP"),"test");flow.step("VERIFY",refund,1);assertEquals("KEEP",f.refunds.business("VERIFY",refund,false).get("goods_action"));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_goods_task",Integer.class));verifyNoInteractions(tasks.inventory);}
 @Test void formulaOnlyPaymentCannotDriveAutomaticCancellation(){rule();f.db.update("UPDATE oms_order SET document_info=JSON_SET(document_info,'$.lines[0].payment_source','销售金额计算')");assertEquals("MANUAL",flow.step("VERIFY",refund,1).get("state"));}
 @Test void sparseListIsSavedWithoutReplacingCompleteRefund(){f.config();RefundApiSupplement api=new RefundApiSupplement();api.refunds=f.refunds;api.platform=mock(RefundPlatformExecution.class);f.db.update("INSERT INTO oms_refund_api_cursor(company_code,channel_id,enabled,cursor_time) VALUES ('VERIFY',1,1,'2026-10-01 00:00:00')");Map<String,Object> sparse=m("refund_id","9007199254740993","tid","987654321012345678","oid","987654321012345679","modified","2026-10-01 00:02:00");when(api.platform.call(eq("VERIFY"),anyMap(),eq("LIST"),anyMap(),anyString(),anyString())).thenReturn(m("refunds",m("refund",Collections.singletonList(sparse)),"has_next",false));assertEquals("DONE",api.page("VERIFY",1,1).get("state"));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_api_item",Integer.class));assertEquals("1",f.db.queryForObject("SELECT refund_version FROM oms_platform_refund",String.class));assertEquals("2026-10-01 00:00:00",text(f.sync.config("VERIFY",1,false),"cursor_time"));when(api.platform.call(eq("VERIFY"),anyMap(),eq("DETAIL"),anyMap(),anyString(),anyString())).thenReturn(m("refund",parse(text(f.source(2,"25.00","WAIT_SELLER_AGREE"),"jdp_response"))));long item=f.db.queryForObject("SELECT id FROM oms_refund_api_item",Long.class);assertEquals("DONE",api.detail("VERIFY",item).get("state"));assertEquals("ORDINARY_API",f.db.queryForObject("SELECT source_kind FROM oms_platform_refund",String.class));}
 @Test void malformedListDoesNotAdvanceApiCursor(){RefundApiSupplement api=new RefundApiSupplement();api.refunds=f.refunds;api.platform=mock(RefundPlatformExecution.class);f.db.update("INSERT INTO oms_refund_api_cursor(company_code,channel_id,enabled,cursor_time) VALUES ('VERIFY',1,1,'2026-10-01 00:00:00')");when(api.platform.call(eq("VERIFY"),anyMap(),eq("LIST"),anyMap(),anyString(),anyString())).thenReturn(m("total_results",2,"has_next",true));assertEquals("WAITING",api.page("VERIFY",1,1).get("state"));assertEquals(1,f.db.queryForObject("SELECT page_no FROM oms_refund_api_cursor",Integer.class));assertTrue(f.db.queryForObject("SELECT last_error FROM oms_refund_api_cursor",String.class).contains("为空"));}
 @Test void goodsScannerEnqueuesOnlyAndDeduplicatesActiveMessage(){long task=adopt(3);f.db.update("DELETE FROM oms_message_outbox WHERE company_code='VERIFY'");com.oms.messaging.MessageOutbox out=new com.oms.messaging.MessageOutbox();out.db=f.db;org.springframework.test.util.ReflectionTestUtils.setField(out,"service","order");org.springframework.test.util.ReflectionTestUtils.setField(out,"transactionManager",new org.springframework.jdbc.datasource.DataSourceTransactionManager(f.db.getDataSource()));org.springframework.beans.factory.ObjectProvider<com.oms.messaging.MessageOutbox> provider=mock(org.springframework.beans.factory.ObjectProvider.class);when(provider.getIfAvailable()).thenReturn(out);org.springframework.test.util.ReflectionTestUtils.setField(f.repo,"messages",provider);tasks.scan("VERIFY");f.db.update("UPDATE oms_refund_goods_task SET next_attempt=NOW() WHERE id=?",task);tasks.scan("VERIFY");assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_message_outbox WHERE company_code='VERIFY' AND message_type='REFUND_GOODS'",Integer.class));assertEquals("order",com.ruoyi.common.core.messaging.QueueKind.of("REFUND_GOODS").service);assertEquals(0,f.db.queryForObject("SELECT cancelled_quantity FROM oms_order_line WHERE id=?",Integer.class,line));verifyNoInteractions(tasks.inventory);f.db.update("DELETE FROM oms_message_outbox WHERE company_code='VERIFY'");}
 RefundPlatformExecution platformExecution(){Map<String,Object> source=f.source(2,"2.00","WAIT_SELLER_AGREE"),parsed=parse(text(source,"jdp_response"));parsed.put("refund_phase","onsale");source.put("jdp_response",encode(m("refund",parsed)));f.ingest(source);f.workspace.review("VERIFY",refund,f.review(refund,"DIFFERENCE","KEEP"),"test");RefundPlatformExecution execution=new RefundPlatformExecution();execution.refunds=f.refunds;execution.channel=mock(RefundPlatformClient.class);when(execution.channel.capability(eq("VERIFY"),eq(1L),anyString())).thenReturn(R.ok(m("can_query",true,"read_enabled",1,"write_enabled",1,"payment_enabled",1,"payment_authorized",true,"ignore_code",1)));when(execution.channel.call(eq("VERIFY"),eq(1L),anyMap(),anyString())).thenAnswer(call->{Map<String,Object> body=call.getArgument(2);String op=text(body,"operation");Map<String,Object> data="DETAIL".equals(op)?m("refund",parsed):"ALLOWED".equals(op)?m("detail",m("refund_version","2","allowed_operations",m("operation",Collections.singletonList(m("operation_code","SELLER_AGREE"))))):"PAY".equals(op)?m("succ",true,"results",m("refund_mapping_result",Collections.singletonList(m("refund_id","9007199254740993","succ",true)))):m("is_success",true);return R.ok(m("outcome","RECEIVED","data",data));});return execution;}
 Map<String,Object> platformInput(){return m("control_version",f.refunds.business("VERIFY",refund,false).get("control_version"),"confirmed",true,"reason","已核对本退款及货物方案","arguments",m());}
 @Test void platformReviewAndPaymentReceiptDoNotInventFinalMoneySuccess(){RefundPlatformExecution execution=platformExecution();execution.submit("VERIFY",refund,"REVIEW",platformInput(),"test");assertEquals("NONE",f.refunds.business("VERIFY",refund,false).get("funds_state"));assertEquals("SUCCESS",f.db.queryForObject("SELECT state FROM oms_refund_operation WHERE action='REVIEW'",String.class));execution.submit("VERIFY",refund,"PAY",platformInput(),"test");assertEquals("NONE",f.refunds.business("VERIFY",refund,false).get("funds_state"));assertEquals("SUCCESS",f.db.queryForObject("SELECT state FROM oms_refund_operation WHERE action='PAY'",String.class));assertThrows(IllegalArgumentException.class,()->execution.submit("VERIFY",refund,"PAY",platformInput(),"test"));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_operation WHERE action='PAY'",Integer.class));verifyNoInteractions(tasks.inventory);}
 @Test void unknownPaymentRequiresOriginalQueryRatherThanNewWrite(){RefundPlatformExecution execution=platformExecution();execution.submit("VERIFY",refund,"REVIEW",platformInput(),"test");when(execution.channel.call(eq("VERIFY"),eq(1L),argThat(body->"PAY".equals(text(body,"operation"))),anyString())).thenReturn(R.ok(m("outcome","UNKNOWN")));execution.submit("VERIFY",refund,"PAY",platformInput(),"test");assertEquals("UNKNOWN",f.db.queryForObject("SELECT state FROM oms_refund_operation WHERE action='PAY'",String.class));assertThrows(IllegalArgumentException.class,()->execution.submit("VERIFY",refund,"PAY",platformInput(),"test"));verify(execution.channel,times(1)).call(eq("VERIFY"),eq(1L),argThat(body->"PAY".equals(text(body,"operation"))),anyString());assertEquals("NONE",f.refunds.business("VERIFY",refund,false).get("funds_state"));}
 @Test void changedAutomaticPolicyStopsPlatformIntentBeforeWrite(){RefundPlatformExecution execution=platformExecution();rule();Map<String,Object> input=platformInput();input.put("auto_policy_revision",2);assertThrows(IllegalArgumentException.class,()->execution.submit("VERIFY",refund,"REVIEW",input,"test"));assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_operation",Integer.class));verify(execution.channel,never()).call(eq("VERIFY"),eq(1L),argThat(body->"REVIEW".equals(text(body,"operation"))),anyString());}
 @Test void finalPlatformMoneyFactClosesUnknownIntentWithoutClaimingOmsPaid(){RefundPlatformExecution execution=platformExecution();execution.submit("VERIFY",refund,"REVIEW",platformInput(),"test");when(execution.channel.call(eq("VERIFY"),eq(1L),argThat(body->"PAY".equals(text(body,"operation"))),anyString())).thenReturn(R.ok(m("outcome","UNKNOWN")));execution.submit("VERIFY",refund,"PAY",platformInput(),"test");Map<String,Object> success=parse(text(f.source(3,"2.00","SUCCESS"),"jdp_response"));success.put("refund_phase","onsale");when(execution.channel.call(eq("VERIFY"),eq(1L),argThat(body->"DETAIL".equals(text(body,"operation"))),anyString())).thenReturn(R.ok(m("outcome","RECEIVED","data",m("refund",success))));execution.reconcile("VERIFY",refund);assertEquals("SUCCESS",f.refunds.business("VERIFY",refund,false).get("funds_state"));assertEquals("CLOSED",f.db.queryForObject("SELECT state FROM oms_refund_operation WHERE action='PAY'",String.class));assertTrue(f.db.queryForObject("SELECT result_message FROM oms_refund_operation WHERE action='PAY'",String.class).contains("未独立确认"));}
 @Test void currentValidJdpDetailAvoidsAnotherVendorDetailRequest(){RefundApiSupplement api=new RefundApiSupplement();api.refunds=f.refunds;api.platform=mock(RefundPlatformExecution.class);f.db.update("INSERT INTO oms_refund_api_cursor(company_code,channel_id,enabled,cursor_time) VALUES ('VERIFY',1,1,'2026-10-01 00:00:00')");Map<String,Object> sparse=m("refund_id","9007199254740993","tid","987654321012345678","oid","987654321012345679","modified","2026-10-01 00:01:00","status","WAIT_SELLER_AGREE","refund_fee","25.00");when(api.platform.call(eq("VERIFY"),anyMap(),eq("LIST"),anyMap(),anyString(),anyString())).thenReturn(m("refunds",m("refund",Collections.singletonList(sparse)),"has_next",false));assertEquals("DONE",api.page("VERIFY",1,1).get("state"));long item=f.db.queryForObject("SELECT id FROM oms_refund_api_item",Long.class);assertEquals("DONE",api.detail("VERIFY",item).get("state"));verify(api.platform,never()).call(eq("VERIFY"),anyMap(),eq("DETAIL"),anyMap(),anyString(),anyString());assertEquals("JDP",f.db.queryForObject("SELECT source_kind FROM oms_platform_refund",String.class));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_platform_refund_snapshot",Integer.class));}
 @Test void sameSecondWithChangedMoneyOrDescriptionStillNeedsFullDetail(){Map<String,Object> source=f.source(1,"25.00","WAIT_SELLER_AGREE"),listed=parse(text(source,"jdp_response")),local=m("source_modified","2026-10-01 00:01:00","payload",source.get("jdp_response"));assertTrue(RefundApiSupplement.locallyCovered(local,listed));listed.put("refund_fee","2.00");assertFalse(RefundApiSupplement.locallyCovered(local,listed));listed.put("refund_fee","25.00");listed.put("desc","新协商申请");assertFalse(RefundApiSupplement.locallyCovered(local,listed));}
 @Test void knownAutomaticPlatformFailureStopsPeriodicResubmission(){RefundPlatformExecution execution=platformExecution();flow.execution=execution;rule();f.db.update("UPDATE oms_refund_flow_policy SET policy_json=JSON_SET(policy_json,'$.auto_review',1)");when(execution.channel.call(eq("VERIFY"),eq(1L),argThat(body->"REVIEW".equals(text(body,"operation"))),anyString())).thenReturn(R.ok(m("outcome","RECEIVED","data",m("is_success",false))));assertEquals("MANUAL",flow.step("VERIFY",refund,1).get("state"));assertEquals("MANUAL",flow.step("VERIFY",refund,1).get("state"));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_refund_operation WHERE action='REVIEW'",Integer.class));verify(execution.channel,times(1)).call(eq("VERIFY"),eq(1L),argThat(body->"REVIEW".equals(text(body,"operation"))),anyString());}
}
